insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('41dec4b3-9e32-5586-af5b-e318ce270029', 'drill-math-algebra', 'Math: Algebra', 'Linear equations, functions, systems, inequalities', 'drill', 'math', 'algebra', 'mixed', 'Linear equations in one and two variables, linear functions, systems and inequalities, including word problems.', 20) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('0a586d8c-5cce-5405-a8a1-78c5e42d4335', '41dec4b3-9e32-5586-af5b-e318ce270029', 1, 'Math: Algebra', 'math', 800) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cbc989b9-037b-5c47-ad97-0c7ffbe9dcd7', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If 4x − 9 = 15, what is the value of x?', '[{"key":"A","text":"1.5"},{"key":"B","text":"6"},{"key":"C","text":"24"},{"key":"D","text":"3"}]'::jsonb, 'B', null, 'Adding 9 gives 4x = 24, so x = 6. Choice C stops after adding 9 and forgets to divide by the coefficient.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('09881a8e-89dd-57a2-a9ab-94f0c709ee1f', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 2, 'algebra', 'linear_functions', 'easy', 'spr', null, 'The function f is defined by f(x) = 5x − 3. What is the value of f(4)?', null, '17', '["17.0"]'::jsonb, 'Substituting 4 gives 5(4) − 3 = 20 − 3 = 17. Answering 23 adds 3 rather than subtracting it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b76e6c5a-cc1a-5c8d-a4be-2b9474e0be97', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 3, 'algebra', 'linear_eq_two_var', 'medium', 'mc', null, 'What is the x-intercept of the line 4x − 5y = 20?', '[{"key":"A","text":"(0, −4)"},{"key":"B","text":"(5, 0)"},{"key":"C","text":"(4, 0)"},{"key":"D","text":"(0, 5)"}]'::jsonb, 'B', null, 'The x-intercept has y = 0, so 4x = 20 and x = 5, giving (5, 0). Choice A is the y-intercept, found by setting x = 0 instead.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('be197c25-f7f3-5e0c-a787-35f579406d88', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 4, 'algebra', 'linear_inequalities', 'medium', 'mc', null, 'A delivery van weighs 1,800 kg empty and each crate weighs 45 kg. The loaded van must not exceed 3,000 kg. What is the greatest number of crates it can carry?', '[{"key":"A","text":"25"},{"key":"B","text":"26"},{"key":"C","text":"27"},{"key":"D","text":"66"}]'::jsonb, 'B', null, 'The available load is 3,000 − 1,800 = 1,200 kg, and 1,200 ÷ 45 = 26.67, so 26 whole crates fit. Choice C rounds up and would exceed the limit by 15 kg.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('064d4af2-5772-555e-ae99-953a4b5dc703', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 5, 'algebra', 'systems_two_linear', 'medium', 'spr', null, 'If 3x + 2y = 19 and x = y + 2, what is the value of y?', null, '2.6', '["13/5","2.60"]'::jsonb, 'Substituting gives 3(y + 2) + 2y = 19, so 5y + 6 = 19 and y = 13/5 = 2.6. Checking, x = 4.6 and 3(4.6) + 2(2.6) = 13.8 + 5.2 = 19.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ab9b0298-c89d-5067-a818-d8498203ce28', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 6, 'algebra', 'linear_functions', 'hard', 'mc', null, 'A tank is drained at a constant rate. After 3 minutes it holds 84 litres, and after 8 minutes it holds 54 litres. How many litres did it hold at the start?', '[{"key":"A","text":"96"},{"key":"B","text":"100"},{"key":"C","text":"102"},{"key":"D","text":"108"}]'::jsonb, 'C', null, 'The rate is (54 − 84)/(8 − 3) = −6 litres per minute, so at t = 0 the volume was 84 + 3(6) = 102 litres. Choice A applies the drop for only two minutes instead of three.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('60bb7bed-0bd3-51af-a9db-3ce58b68ba0d', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 7, 'algebra', 'linear_eq_one_var', 'hard', 'mc', null, 'For what value of a does the equation 2(3x − a) = 6x + 8 have infinitely many solutions?', '[{"key":"A","text":"a = −4"},{"key":"B","text":"a = 4"},{"key":"C","text":"a = 8"},{"key":"D","text":"a = −8"}]'::jsonb, 'A', null, 'Expanding the left side gives 6x − 2a, and since the 6x terms match, the equation holds for every x only when the constants match: −2a = 8, so a = −4. Choice B is the sign error made by solving 2a = 8 and forgetting the minus sign, and any other value of a makes the equation false for every x.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('3a84688e-7e07-5ac2-a5d1-654eaaaa0d0f', '0a586d8c-5cce-5405-a8a1-78c5e42d4335', 8, 'algebra', 'linear_inequalities', 'hard', 'spr', null, 'What is the least integer value of n that satisfies 7 − 2n < n − 8?', null, '6', '["6.0"]'::jsonb, 'Adding 2n and 8 to both sides gives 15 < 3n, so n > 5 and the least integer is 6. Answering 5 ignores that the inequality is strict, and n = 5 gives −3 < −3, which is false.') on conflict (id) do nothing;
